import json

payload = json.loads('{"id": 7, "name": "Ana", "legacy_code": "X9", "temp_flag": true}')
KNOWN = ("id", "name")

def keep(p):
    return dict(p)

def drop(p):
    return {k: p[k] for k in KNOWN if k in p}

def reject(p):
    extra = sorted(set(p) - set(KNOWN))
    if extra:
        raise ValueError(f"unknown fields: {extra}")
    return dict(p)

print("keep:  ", keep(payload))
print("drop:  ", drop(payload))
try:
    reject(payload)
except ValueError as e:
