def dig(obj, *path):
    cur, walked = obj, []
    for key in path:
        walked.append(str(key))
        if isinstance(cur, dict) and key in cur:
            cur = cur[key]
        else:
            return f"stopped at {'.'.join(walked)}: {type(cur).__name__} has no key {key!r}"
