import copy

defaults = {"db": {"host": "localhost", "port": 5432},
            "plugins": [{"name": "auth", "on": True},
                        {"name": "cache", "on": False}],
            "banner": "welcome"}
env = {"db": {"port": 5433},
       "plugins": [{"name": "cache", "on": True},
                   {"name": "metrics", "on": True}]}
user = {"banner": None, "db": {"host": "db.internal"}}
defaults_snapshot = copy.deepcopy(defaults)

def merge_plugins(a, b):
    out = {p["name"]: dict(p) for p in a}
    for p in b:
        if p["name"] in out:
            out[p["name"]].update(p)
        else:
            out[p["name"]] = dict(p)
    return list(out.values())

def deep_merge(a, b):
    out = dict(a)
    for k, v in b.items():
        if v is None:
            out.pop(k, None)  # null in a higher layer deletes the key
        elif k == "plugins":
            out[k] = merge_plugins(out.get(k, []), v)
        elif k in out and isinstance(out[k], dict) and isinstance(v, dict):
            out[k] = deep_merge(out[k], v)
        else:
            out[k] = v
    return out

cfg = deep_merge(deep_merge(defaults, env), user)
print("final:", cfg)
print("defaults untouched:", defaults == defaults_snapshot)

