import copy

def make_patch(a, b, path=()):
    ops = []
    if isinstance(a, dict) and isinstance(b, dict):
        for k in b:
            if k not in a:
                ops.append(("set", path + (k,), b[k]))
            else:
                ops += make_patch(a[k], b[k], path + (k,))
        for k in a:
            if k not in b:
                ops.append(("remove", path + (k,), None))
    elif a != b:
        ops.append(("set", path, b))
    return ops

def apply_patch(doc, ops):
    doc = copy.deepcopy(doc)
    for action, path, value in ops:
        cur = doc
        for k in path[:-1]:
            cur = cur[k]
        if action == "set":
            cur[path[-1]] = value
        else:
            del cur[path[-1]]
    return doc

old = {"a": 1, "b": {"x": 1, "y": 2}, "gone": True}
new = {"a": 1, "b": {"x": 9}, "c": "new"}
