SCHEMA = {
    "type": "object",
    "required": ["name", "address"],
    "properties": {
        "name": {"type": "string"},
        "age": {"type": "integer"},
        "address": {
            "type": "object",
            "required": ["zip"],
            "properties": {"zip": {"type": "string"},
                           "city": {"type": "string"}},
        },
    },
}

def validate(value, schema, path=""):
    errs = []
    t = schema["type"]
    if t == "object":
        if not isinstance(value, dict):
            return [f"{path or '.'}: expected object, got {type(value).__name__}"]
        for req in schema.get("required", []):
            if req not in value:
                errs.append(f"{path}{req}: missing required field")
        for key, sub in schema.get("properties", {}).items():
            if key in value:
                errs += validate(value[key], sub, f"{path}{key}.")
    elif t == "string":
        if not isinstance(value, str):
            errs.append(f"{path[:-1]}: expected string, got {type(value).__name__}")
    elif t == "integer":
        if type(value) is not int:
            errs.append(f"{path[:-1]}: expected integer, got {type(value).__name__}")
    return errs

