import re

SKU = re.compile(r"^[A-Z]{3}-\d{4}$")
REGIONS = {"us", "eu", "apac"}

def check_order(p):
    errs = []
    if not SKU.match(p.get("sku", "")):
        errs.append(f"sku: {p.get('sku')!r} does not match AAA-0000 pattern")
    qty = p.get("qty")
    if type(qty) is not int or not (1 <= qty <= 999):
        errs.append(f"qty: expected int in 1..999, got {qty!r}")
    price = p.get("price")
    if isinstance(price, bool) or not isinstance(price, (int, float)) or price < 0:
        errs.append(f"price: expected non-negative number, got {price!r}")
    if p.get("region") not in REGIONS:
        errs.append(f"region: {p.get('region')!r} not in {sorted(REGIONS)}")
    note = p.get("note", "")
    if len(note) > 80:
        errs.append(f"note: {len(note)} chars exceeds 80")
    return errs

