import json

def no_dupes(pairs):
    obj = {}
    for k, v in pairs:
        if k in obj:
            raise ValueError(f"duplicate key {k!r}")
        obj[k] = v
    return obj

KNOWN = ("name", "email", "plan")
DEFAULTS = {"plan": "free"}

def boundary_parse(text):
    raw = json.loads(text, object_pairs_hook=no_dupes)
    dropped = sorted(set(raw) - set(KNOWN))
    rec = {k: raw[k] for k in KNOWN if k in raw}
    for field in ("name", "email"):
        if not isinstance(rec.get(field), str):
            raise ValueError(f"{field}: required string")
    for k, v in DEFAULTS.items():
        rec.setdefault(k, v)
    return rec, dropped

